package agentusageview

import (
	"errors"
	"fmt"
	"io/fs"
	"math/rand"
	"os"
	"path/filepath"
	"reflect"
	"regexp"
	"strings"
	"sync"
	"testing"
	"time"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// Live updates, step 4 (DEVDESK-45): the poll chain (answer, wait pollInterval,
// read, answer...) and the rule that stops it. Option A of the plan:
// quietPeriod 5 min, a settled session or a deleted transcript ends the chain.
// Leave/resume (step 5) and the header's live/paused slot (step 6) are not here.

var ansiRe = regexp.MustCompile(`\x1b\[[0-9;]*m`)

// ── Helpers ──────────────────────────────────────────────────────────────────

// usageLine is one assistant transcript line for message msgID.
func usageLine(msgID, model string, in, out int) string {
	return fmt.Sprintf(`{"type":"assistant","uuid":"u-%[1]s","message":{"id":%[1]q,"model":%[2]q,"role":"assistant","stop_reason":"end_turn","content":[],"usage":{"input_tokens":%[3]d,"output_tokens":%[4]d,"cache_read_input_tokens":0,"cache_creation_input_tokens":0}}}`,
		msgID, model, in, out)
}

// appendLine appends line and a newline to path.
func appendLine(t *testing.T, path, line string) {
	t.Helper()
	appendRaw(t, path, line+"\n")
}

func appendRaw(t *testing.T, path, s string) {
	t.Helper()
	f, err := os.OpenFile(path, os.O_APPEND|os.O_WRONLY|os.O_CREATE, 0o600)
	if err != nil {
		t.Error(err)
		return
	}
	defer func() {
		if err := f.Close(); err != nil {
			t.Error(err)
		}
	}()
	if _, err := f.WriteString(s); err != nil {
		t.Error(err)
	}
}


// subDir is the sub-agents directory of the copied session.
func subDir(parent string) string {
	return filepath.Join(strings.TrimSuffix(parent, ".jsonl"), "subagents")
}

// finishTester flips the fixture's one unfinished sub-agent (a02) to finished,
// so nothing keeps the session alive but the recency of its files.
func finishTester(t *testing.T, parent string) {
	t.Helper()
	p := filepath.Join(subDir(parent), "agent-a02.meta.json")
	raw, err := os.ReadFile(p)
	if err != nil {
		t.Fatal(err)
	}
	edited := strings.Replace(string(raw), `"finished":false`, `"finished":true`, 1)
	if edited == string(raw) {
		t.Fatal("the fixture's a02 meta no longer says finished:false")
	}
	if err := os.WriteFile(p, []byte(edited), 0o600); err != nil {
		t.Fatal(err)
	}
}

// ageAll sets every file of the session (and its directories) d in the past.
func ageAll(t *testing.T, parent string, d time.Duration) {
	t.Helper()
	when := time.Now().Add(-d)
	for _, root := range []string{parent, strings.TrimSuffix(parent, ".jsonl")} {
		err := filepath.WalkDir(root, func(p string, _ fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			return os.Chtimes(p, when, when)
		})
		if err != nil {
			t.Fatal(err)
		}
	}
}

// ticksOf keeps the poll ticks among msgs.
func ticksOf(msgs []tea.Msg) []usagePollTickMsg {
	var got []usagePollTickMsg
	for _, m := range msgs {
		if tk, ok := m.(usagePollTickMsg); ok {
			got = append(got, tk)
		}
	}
	return got
}

// runCmd runs cmd with a short poll interval and returns what it produced.
func runCmd(t *testing.T, cmd tea.Cmd) []tea.Msg {
	t.Helper()
	testutil.FastTimers(t, &pollInterval)
	return batchMsgs(t, cmd)
}

// answered feeds msg to m (which must have a read in flight) and returns the
// model and the messages the returned Cmd produced.
func answered(t *testing.T, m Model, msg usageDeltaMsg) (Model, []tea.Msg) {
	t.Helper()
	// Before Update: pollTickCmd freezes pollInterval when it is built.
	testutil.FastTimers(t, &pollInterval)
	updated, cmd := m.Update(msg)
	return updated.(Model), runCmd(t, cmd)
}

// pollTick delivers a tick of gen to m.
func pollTick(t *testing.T, m Model, gen int) (Model, []tea.Msg) {
	t.Helper()
	updated, cmd := m.Update(usagePollTickMsg{gen: gen})
	return updated.(Model), batchMsgs(t, cmd)
}


const logTag = "ERROR [agentusageview]"

// openedFixture opens a copy of the basic fixture and returns the model, the
// copy's parent transcript, and the Cmd the open returned.
func openedFixture(t *testing.T) (Model, string, tea.Cmd) {
	t.Helper()
	parent := copyFixture(t)
	m := withSessions(t, parent)
	m, cmd := opened(t, m, "right")
	return m, parent, cmd
}

// firstDelta runs a Cmd and returns the single usageDeltaMsg it produced.
func firstDelta(t *testing.T, cmd tea.Cmd) usageDeltaMsg {
	t.Helper()
	got := usageMsgs(batchMsgs(t, cmd))
	if len(got) != 1 {
		t.Fatalf("want exactly one usageDeltaMsg, got %d: %+v", len(got), got)
	}
	return got[0]
}

// atFixture opens a fixture copy and delivers the answer to the open.
func atFixture(t *testing.T) (Model, string) {
	t.Helper()
	m, parent, cmd := openedFixture(t)
	return feed(t, m, firstDelta(t, cmd)), parent
}

// captureLog redirects the standard logger for the test.
func captureLog(t *testing.T) *bytes.Buffer {
	t.Helper()
	var buf bytes.Buffer
	log.SetOutput(&buf)
	t.Cleanup(func() { log.SetOutput(os.Stderr) })
	return &buf
}

// mainOutput is the orchestrator's output token count on screen.
func mainOutput(t *testing.T, m Model) int64 {
	t.Helper()
	for _, a := range m.usage.Agents {
		if a.Main {
			return a.Tokens.Output
		}
	}
	t.Fatal("no orchestrator in the usage")
	return 0
}

package app

import (
	"testing"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/anthnel/devdesk/internal/command"
)

// leavingView is a fakeView that also answers LeavingView, which fakeView
// deliberately does not: the router's fallback for a view without the interface
// is a path worth keeping under test, and every other test exercises it.
type leavingView struct {
	fakeView
	allow  bool
	cmd    tea.Cmd
	leaves int
}

func (v *leavingView) Leave() (tea.Model, tea.Cmd, bool) {
	v.leaves++
	return v, v.cmd, v.allow
}

func newAppWithLeaver(t *testing.T, allow bool) (*App, *leavingView) {
	t.Helper()
	app := newWithSize(testConfig(), 120, 40)
	leaver := &leavingView{allow: allow}
	app.views[command.ViewConfiguration] = leaver
	app.currentView = command.ViewConfiguration
	return app, leaver
}

// The defect the interface exists for: switchView told nobody, so a view
// holding an uncommitted edit lost it without a word (§1.3 D62).
func TestSwitchViewSettlesTheViewItLeaves(t *testing.T) {
	app, leaver := newAppWithLeaver(t, true)

	app.switchView(command.ViewWorkspaces)

	if leaver.leaves != 1 {
		t.Errorf("Leave() called %d times, want 1", leaver.leaves)
	}
	if app.currentView != command.ViewWorkspaces {
		t.Errorf("currentView = %q, want the switch to have happened", app.currentView)
	}
}

// A refusal keeps the screen, and carries what the view wants to say about it.
func TestARefusingViewCancelsTheSwitch(t *testing.T) {
	app, leaver := newAppWithLeaver(t, false)
	leaver.cmd = func() tea.Msg { return "refused" }

