func TestAQuickReturnLeavesExactlyOneChain(t *testing.T) {
	m, _ := atFixture(t)
	oldTick := m.agentGen
	m, _, _ = leave(t, m)
	m, cmd := resumed(t, m)
	reads := usageMsgs(batchMsgs(t, cmd))
	if len(reads) != 1 {
